@import "tailwindcss/theme.css" layer(theme);
@import "tailwindcss/preflight.css" layer(base);

@theme {
  --color-gs-wine: #511C2F;
  --color-gs-paper: #F4E7D1;
  --color-gs-red: #E45D3D;
  --color-gs-teal: #102F38;
  --color-gs-lime: #E7F584;
}
:root { --gs-wine:#511C2F; --gs-paper:#F4E7D1; --gs-red:#E45D3D; --gs-teal:#102F38; --gs-lime:#E7F584; --gs-red-paper:color-mix(in srgb,var(--gs-red) 80%,var(--gs-paper)); --gs-red-ink:color-mix(in srgb,var(--gs-red) 85%,var(--gs-wine)); --gs-ease:cubic-bezier(.22,1,.36,1); --gs-wipe:cubic-bezier(.76,0,.24,1); --gs-fast:180ms; --gs-base:420ms; --gs-slow:800ms; --gs-progress:0; }
* { box-sizing:border-box; }
html { scroll-behavior:smooth; }
.gs-body { margin:0; background:var(--gs-paper); color:var(--gs-wine); font-family:var(--font-gs-dm),sans-serif; overflow-x:clip; }
.gs-body button,.gs-body select { font:inherit; }
.gs-body button { cursor:pointer; }
.gs-body button:disabled { cursor:not-allowed; opacity:.5; }
.gs-body a { color:inherit; text-decoration:none; }
.gs-body img,.gs-body svg { display:block; }
.gs-body img { width:100%; height:100%; object-fit:cover; }
.gs-body picture { display:block; }
.gs-body :focus-visible { outline:3px solid var(--gs-red); outline-offset:4px; }
.gs-skip { position:fixed; left:1rem; top:1rem; z-index:100; transform:translateY(-200%); background:var(--gs-lime); color:var(--gs-teal); padding:.8rem; }
.gs-skip:focus { transform:none; }
.gs-sr-only { position:absolute; width:1px; height:1px; overflow:hidden; clip-path:inset(50%); white-space:nowrap; }
.gs-kicker,.gs-masthead-note,.gs-schedule,.gs-ticket-top,.gs-ticket-bottom,.gs-stage-caption,.gs-stage-index,.gs-section-top,.gs-poster-overlay>span,.gs-poster-overlay small,.gs-poster-stamp,.gs-season-note,.gs-disclaimer,.gs-production-row>span,.gs-plan-title,.gs-zoom,.gs-legend,.gs-demo-note,.gs-summary-top,.gs-summary-detail>span,.gs-summary-total>span,.gs-summary-foot,.gs-reset,.gs-alternative,.gs-receipt-header,.gs-receipt-line,.gs-cast-image>span,.gs-cast-number,.gs-company-quote small,.gs-visit-facts span,.gs-venue-map,.gs-finale-stub>span,.gs-footer-bottom,.gs-curtain-overline { font-family:var(--font-gs-mono),monospace; font-size:10px; line-height:1.5; font-weight:500; letter-spacing:.06em; }
.gs-kicker { margin:0; text-transform:uppercase; }
.gs-lime { color:var(--gs-lime); }
.gs-logo { display:inline-flex; align-items:center; gap:10px; font-family:var(--font-gs-anton),Impact,sans-serif; font-size:25px; letter-spacing:.01em; line-height:1; }
.gs-logo svg { width:30px; height:30px; }
.gs-logo-dot { color:var(--gs-red-ink); }
.gs-header { position:relative; z-index:5; background:var(--gs-paper); }
.gs-masthead { min-height:76px; padding:0 4.2%; display:flex; align-items:center; gap:28px; }
.gs-masthead-note { margin-left:auto; opacity:.8; }
.gs-header-cta { align-self:stretch; display:flex; align-items:center; gap:36px; padding:0 23px; background:var(--gs-wine); color:var(--gs-paper)!important; font-family:var(--font-gs-mono),monospace; font-size:10px; letter-spacing:.04em; transition:background var(--gs-base) var(--gs-ease); }
.gs-header-cta:hover { background:var(--gs-teal); }
.gs-header-cta span,.gs-button span,.gs-text-link span { transition:transform var(--gs-base) var(--gs-ease); }
.gs-header-cta:hover span,.gs-button:hover span,.gs-text-link:hover span { transform:translate(3px,-3px); }
.gs-menu-button { display:none; }
.gs-schedule { min-height:42px; display:flex; align-items:stretch; padding:0 4.2%; border-top:1px solid var(--gs-wine); border-bottom:1px solid var(--gs-wine); }
.gs-schedule a,.gs-schedule-label,.gs-schedule-end { display:flex; align-items:center; padding:0 22px; border-right:1px solid color-mix(in srgb,var(--gs-wine) 35%,transparent); }
.gs-schedule-label { padding-left:0; gap:4px; }
.gs-schedule-label b { font-weight:400; opacity:.7; }
.gs-schedule a { text-transform:uppercase; transition:background var(--gs-fast),color var(--gs-fast); }
.gs-schedule a:hover { background:var(--gs-wine); color:var(--gs-paper); }
.gs-schedule-end { margin-left:auto; border:0; padding-right:0; gap:9px; }
.gs-schedule-end i { font-style:normal; color:var(--gs-red); font-size:17px; }
.gs-progress { height:3px; background:var(--gs-red); transform:scaleX(var(--gs-progress)); transform-origin:left; position:absolute; bottom:-3px; left:0; right:0; }
.gs-drawer,.gs-receipt { border:0; color:var(--gs-paper); background:var(--gs-wine); max-width:none; max-height:none; }
.gs-drawer::backdrop,.gs-receipt::backdrop { background:color-mix(in srgb,var(--gs-teal) 75%,transparent); }
.gs-drawer { position:fixed; margin:0 0 0 auto; inset:0 0 0 auto; width:min(100%,500px); height:100dvh; padding:24px; }
.gs-drawer-top { display:flex; justify-content:space-between; align-items:center; }
.gs-drawer-top button,.gs-receipt-header button { background:none; color:inherit; border:1px solid currentColor; padding:10px; }
.gs-drawer nav { margin-top:12vh; }
.gs-drawer nav a { display:flex; align-items:center; gap:16px; border-top:1px solid currentColor; padding:16px 0; font-family:var(--font-gs-anton),sans-serif; font-size:clamp(30px,8vw,55px); text-transform:uppercase; }
.gs-drawer nav a small { font:11px var(--font-gs-mono),monospace; }
.gs-drawer nav a span { margin-left:auto; font-size:25px; }
.gs-drawer>p { margin-top:50px; font:11px/1.6 var(--font-gs-mono),monospace; }
.gs-hero { min-height:min(720px,calc(100svh - 118px)); display:grid; grid-template-columns:minmax(325px,35%) 1fr; }
.gs-ticket { position:relative; background:var(--gs-red-paper); display:flex; flex-direction:column; padding:23px clamp(24px,3.5vw,62px) 0; }
.gs-ticket:after { position:absolute; content:""; right:-9px; top:0; bottom:0; z-index:2; width:18px; background:radial-gradient(circle at 50% 9px,transparent 0 8px,var(--gs-red-paper) 8.5px) 0 0/18px 26px; }
.gs-ticket-top { display:flex; justify-content:space-between; gap:15px; padding-bottom:22px; border-bottom:1px solid var(--gs-wine); }
.gs-ticket-body { flex:1; padding:clamp(34px,5vh,70px) 0; }
.gs-ticket-body .gs-kicker span { color:var(--gs-wine); font-size:18px; vertical-align:middle; }
.gs-ticket h1,.gs-season h2,.gs-seats h2,.gs-company h2,.gs-visit h2,.gs-finale h2,.gs-curtain-content h2 { font-family:var(--font-gs-anton),Impact,sans-serif; font-weight:400; letter-spacing:-.025em; line-height:.92; margin:20px 0; }
.gs-ticket h1 { font-size:clamp(68px,7.3vw,130px); }
.gs-ticket h1>span { display:block; }
.gs-period { color:var(--gs-teal); }
.gs-hero-copy { font-size:clamp(16px,1.3vw,20px); line-height:1.4; margin:23px 0 26px; }
.gs-hero-actions { display:flex; align-items:flex-start; flex-direction:column; gap:20px; }
.gs-button { display:inline-flex; align-items:center; justify-content:space-between; gap:40px; border:1px solid currentColor; min-height:52px; padding:14px 18px; font-weight:700; font-size:14px; transition:transform var(--gs-fast) var(--gs-ease),background var(--gs-base) var(--gs-ease),color var(--gs-base) var(--gs-ease); }
.gs-button-dark { background:var(--gs-wine); color:var(--gs-paper)!important; border-color:var(--gs-wine); }
.gs-button-dark:hover { background:var(--gs-teal); border-color:var(--gs-teal); }
.gs-button-lime { background:var(--gs-lime); color:var(--gs-teal)!important; border-color:var(--gs-lime); }
.gs-button-lime:hover { background:var(--gs-paper); border-color:var(--gs-paper); }
.gs-button:active { transform:scale(.97); }
.gs-text-link { display:inline-flex; gap:18px; align-items:center; font-size:13px; font-weight:700; text-decoration:underline!important; text-underline-offset:5px; }
.gs-ticket-bottom { display:flex; justify-content:space-between; align-items:center; gap:12px; border-top:1px dashed var(--gs-wine); min-height:85px; }
.gs-barcode { width:65px; height:31px; background:repeating-linear-gradient(90deg,var(--gs-wine) 0 2px,transparent 2px 4px,var(--gs-wine) 4px 5px,transparent 5px 8px); }
.gs-hero-stage { position:relative; overflow:hidden; min-height:450px; background:var(--gs-teal); color:var(--gs-paper); }
.gs-hero-stage>picture { position:absolute; inset:0; }
.gs-hero-stage img { object-position:center; }
.gs-stage-shade { position:absolute; inset:0; background:linear-gradient(180deg,color-mix(in srgb,var(--gs-teal) 42%,transparent),transparent 42%,color-mix(in srgb,var(--gs-teal) 70%,transparent)); }
.gs-stage-caption { position:absolute; bottom:26px; left:5%; right:5%; display:flex; justify-content:space-between; }
.gs-stage-index { position:absolute; top:24px; right:5%; display:flex; align-items:baseline; gap:5px; }
.gs-stage-index span:first-child { font:40px var(--font-gs-anton),sans-serif; }
.gs-curtain-section { height:190svh; background:var(--gs-teal); color:var(--gs-paper); --gs-cue:1; }
.gs-curtain-sticky { position:sticky; top:0; height:100svh; padding:clamp(15px,3vw,45px); }
.gs-curtain-scene { position:relative; height:100%; overflow:hidden; }
.gs-curtain-scene>picture { position:absolute; inset:0; }
.gs-curtain-scene:after { content:""; position:absolute; inset:0; background:linear-gradient(180deg,color-mix(in srgb,var(--gs-teal) 20%,transparent),color-mix(in srgb,var(--gs-teal) 78%,transparent)); }
.gs-curtain-panel { position:absolute; z-index:1; top:0; bottom:0; width:51%; background:repeating-linear-gradient(90deg,var(--gs-wine),color-mix(in srgb,var(--gs-wine) 78%,var(--gs-teal)) 7%,var(--gs-wine) 15%); }
.gs-curtain-left { left:0; transform:translateX(calc(var(--gs-cue) * -100%)); }
.gs-curtain-right { right:0; transform:translateX(calc(var(--gs-cue) * 100%)); }
.gs-curtain-light { position:absolute; z-index:2; inset:0; background:radial-gradient(ellipse at 50% 0%,color-mix(in srgb,var(--gs-lime) 30%,transparent),transparent 60%); opacity:var(--gs-cue); pointer-events:none; }
.gs-curtain-content { position:absolute; z-index:3; inset:0; padding:4%; display:flex; flex-direction:column; justify-content:space-between; }
.gs-curtain-overline { display:flex; justify-content:space-between; }
.gs-curtain-content h2 { font-size:clamp(48px,7.5vw,118px); }
.gs-curtain-content em,.gs-season h2 em,.gs-seats h2 em,.gs-company h2 em,.gs-visit h2 em,.gs-finale h2 em { color:var(--gs-red); font-style:normal; }
.gs-section { padding:clamp(65px,9vw,140px) 5%; }
.gs-section-top { display:flex; justify-content:space-between; gap:20px; padding-top:13px; border-top:1px solid currentColor; }
.gs-section-top p { margin:0; }
.gs-section-top p:last-child { text-align:right; }
.gs-section-top-light { color:var(--gs-paper); }
.gs-season-heading,.gs-company-heading,.gs-seats-heading { display:flex; justify-content:space-between; align-items:end; gap:30px; margin:clamp(55px,8vw,120px) 0 50px; }
.gs-season h2,.gs-company h2,.gs-seats h2,.gs-visit h2,.gs-finale h2 { font-size:clamp(48px,7vw,110px); margin:0; }
.gs-season-heading>p,.gs-company-heading>p,.gs-seats-heading>p { max-width:310px; font-size:16px; line-height:1.55; margin:0 0 5px; }
.gs-production-layout { display:grid; grid-template-columns:1fr .7fr; gap:5%; border-top:1px solid var(--gs-wine); padding-top:25px; }
.gs-production-list { display:flex; flex-direction:column; }
