.gs-production-row { color:var(--gs-wine); background:none; border:0; border-bottom:1px solid var(--gs-wine); display:grid; grid-template-columns:1fr auto; gap:14px; text-align:left; padding:23px 12px; transition:background var(--gs-base) var(--gs-ease),color var(--gs-base) var(--gs-ease); }
