.gs-poster-stage { position:relative; aspect-ratio:3/4; max-height:650px; overflow:hidden; background:var(--gs-wine); color:var(--gs-paper); }
.gs-poster-stage>picture { position:absolute; inset:0; }
.gs-poster-stage:after { content:""; position:absolute; inset:0; background:linear-gradient(180deg,color-mix(in srgb,var(--gs-wine) 45%,transparent),transparent 60%,color-mix(in srgb,var(--gs-wine) 55%,transparent)); pointer-events:none; }
.gs-poster-overlay { position:absolute; z-index:1; inset:0; padding:6%; display:flex; flex-direction:column; justify-content:space-between; }
.gs-poster-overlay strong { display:flex; flex-direction:column; font:clamp(45px,5vw,80px)/.9 var(--font-gs-anton),sans-serif; letter-spacing:-.02em; }
.gs-poster-stamp { position:absolute; z-index:2; top:5%; right:5%; border:1px solid currentColor; padding:8px; text-align:center; transform:rotate(6deg); }
.gs-season-note { margin-top:20px; display:flex; justify-content:space-between; align-items:end; gap:20px; }
.gs-season-note p { font-family:var(--font-gs-dm),sans-serif; font-size:15px; }
.gs-season-note p span { font:10px var(--font-gs-mono),monospace; }
.gs-disclaimer { margin-top:24px; opacity:.8; }
.gs-seats { background:var(--gs-teal); color:var(--gs-paper); }
.gs-seats-heading { margin-bottom:60px; }
.gs-seats-heading .gs-kicker { margin-bottom:24px; }
.gs-seats h2 em { color:var(--gs-lime); }
.gs-seat-layout { display:grid; grid-template-columns:minmax(0,1fr) minmax(270px,330px); gap:24px; align-items:start; }
