.gs-receipt .gs-button { width:100%; }
.gs-mobile-summary { display:none; }
.gs-noscript { margin:0; padding:16px 5%; background:var(--gs-teal); color:var(--gs-paper); }
.gs-company-grid { display:grid; grid-template-columns:1.5fr .65fr; gap:30px; }
